@inject ISettingsService SettingsService

<div class="settings-section">
    <h4 class="section-heading">Security</h4>
    <p class="text-secondary">Manage your password, two-factor authentication, and sessions.</p>

    @if (_loading)
    {
        <div class="text-center py-4">
            <div class="spinner-border text-primary" role="status">
                <span class="visually-hidden">Loading…</span>
            </div>
        </div>
    }
    else
    {
        @* Change Password Panel *@
        <div class="card mb-4">
            <div class="card-header d-flex justify-content-between align-items-center"
                 role="button" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                <h6 class="mb-0">Change Password</h6>
                <span class="expand-icon">@(_passwordPanelOpen ? "▲" : "▼")</span>
            </div>
            @if (_passwordPanelOpen)
            {
                <div class="card-body">
                    <div class="mb-3">
                        <label class="form-label" for="currentPwd">Current Password</label>
                        <input id="currentPwd" type="password" class="form-control"
                               @bind="_currentPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label" for="newPwd">New Password</label>
                        <input id="newPwd" type="password" class="form-control"
                               @bind="_newPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label" for="confirmPwd">Confirm Password</label>
                        <input id="confirmPwd" type="password" class="form-control"
                               @bind="_confirmPassword" />
                    </div>

                    @if (_passwordError is not null)
                    {
                        <div class="alert alert-danger py-2">@_passwordError</div>
                    }
                    @if (_passwordSuccess is not null)
                    {
                        <div class="alert alert-success py-2">@_passwordSuccess</div>
                    }

                    <button class="btn btn-primary" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
                        @if (_changingPassword)
                        {
                            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                        }
                        Update Password
                    </button>
                </div>
            }
        </div>

        @* Two-Factor Authentication *@
        <div class="card mb-4">
            <div class="card-body d-flex justify-content-between align-items-center">
                <div>
                    <h6 class="mb-1">Two-Factor Authentication</h6>
                    <small class="text-muted">
                        Status:
                        @if (_twoFactorEnabled)
                        {
                            <span class="badge bg-success">Enabled</span>
                        }
                        else
                        {
                            <span class="badge bg-warning text-dark">Disabled</span>
                        }
                    </small>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" role="switch"
                           id="twoFactor" @bind="_twoFactorEnabled" />
                </div>
            </div>
        </div>

        @* Active Sessions *@
        <div class="card mb-4">
            <div class="card-header">
                <h6 class="mb-0">Active Sessions</h6>
            </div>
            <div class="card-body p-0">
                @if (_sessions.Count == 0)
                {
                    <p class="text-muted p-3 mb-0">No active sessions.</p>
                }
                else
                {
                    <div class="table-responsive">
                        <table class="table table-hover mb-0">
                            <thead>
                                <tr>
                                    <th>Device</th>
                                    <th>Location</th>
                                    <th>Last Active</th>
                                    <th></th>
                                </tr>
                            </thead>
                            <tbody>
                                @foreach (var session in _sessions)
                                {
                                    <tr>
                                        <td>@session.Device</td>
                                        <td>@session.Location</td>
                                        <td>@session.LastActive.ToString("g")</td>
                                        <td class="text-end">
                                            @if (session != _sessions[0])
                                            {
                                                <button class="btn btn-sm btn-outline-danger"
                                                        @onclick="() => PromptRevoke(session)"
                                                        disabled="@(_revokingSessionId == session.Id)">
                                                    @if (_revokingSessionId == session.Id)
                                                    {
                                                        <span class="spinner-border spinner-border-sm" role="status"></span>
                                                    }
                                                    else
                                                    {
                                                        <span>Revoke</span>
                                                    }
                                                </button>
                                            }
                                            else
                                            {
                                                <span class="badge bg-info text-dark">Current</span>
                                            }
                                        </td>
                                    </tr>
                                }
                            </tbody>
                        </table>
                    </div>
                }
            </div>
        </div>

        @* Revoke Confirmation Dialog *@
        @if (_sessionToRevoke is not null)
        {
            <div class="modal-backdrop show"></div>
            <div class="modal d-block" tabindex="-1" role="dialog">
                <div class="modal-dialog modal-dialog-centered" role="document">
                    <div class="modal-content">
                        <div class="modal-header">
                            <h5 class="modal-title">Revoke Session</h5>
                            <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                        </div>
                        <div class="modal-body">
                            <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                            <p class="text-muted mb-0">This will sign out the device immediately.</p>
                        </div>
                        <div class="modal-footer">
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                            <button class="btn btn-danger" @onclick="ConfirmRevokeAsync">Revoke</button>
                        </div>
                    </div>
                </div>
            </div>
        }
    }
</div>

@code {
    private bool _loading = true;
    private bool _passwordPanelOpen;
    private bool _changingPassword;
    private bool _twoFactorEnabled;

    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordError;
    private string? _passwordSuccess;

    private List<ActiveSession> _sessions = new();
    private ActiveSession? _sessionToRevoke;
    private string? _revokingSessionId;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        try
        {
            var settings = await SettingsService.GetSecuritySettingsAsync();
            _twoFactorEnabled = settings.TwoFactorEnabled;
            _sessions = settings.Sessions.ToList();
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task ChangePasswordAsync()
    {
        _passwordError = null;
        _passwordSuccess = null;

        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "New password is required.";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _passwordError = "Passwords do not match.";
            return;
        }

        _changingPassword = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _passwordSuccess = "Password updated successfully.";
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _passwordError = $"Failed to change password: {ex.Message}";
        }
        finally
        {
            _changingPassword = false;
        }
    }

    private void PromptRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is null) return;

        var sessionId = _sessionToRevoke.Id;
        _revokingSessionId = sessionId;
        _sessionToRevoke = null;

        try
        {
            await SettingsService.RevokeSessionAsync(sessionId);
            _sessions.RemoveAll(s => s.Id == sessionId);
        }
        catch
        {
            // Session may have already been revoked
        }
        finally
        {
            _revokingSessionId = null;
        }
    }
}

@inject ISettingsService SettingsService

<div class="settings-section">
    <h4 class="section-heading">Appearance</h4>
    <p class="text-secondary">Customize how the application looks.</p>

    @if (_loading)
    {
        <div class="text-center py-4">
            <div class="spinner-border text-primary" role="status">
                <span class="visually-hidden">Loading…</span>
            </div>
        </div>
    }
    else
    {
        <div class="row g-4">
            <div class="col-md-7">
                @* Theme Selector *@
                <div class="card mb-4">
                    <div class="card-body">
                        <h6 class="card-title">Theme</h6>
                        @foreach (var theme in _themes)
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="@($"theme-{theme.ToLowerInvariant()}")"
                                       value="@theme"
                                       checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme.ToLowerInvariant()}")">
                                    @theme
                                </label>
                            </div>
                        }
                    </div>
                </div>

                @* Font Size Selector *@
                <div class="card mb-4">
                    <div class="card-body">
                        <h6 class="card-title">Font Size</h6>
                        @foreach (var size in _fontSizes)
                        {
                            <div class="form-check form-check-inline">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="@($"fs-{size.ToLowerInvariant()}")"
                                       value="@size"
                                       checked="@(_fontSize == size)"
                                       @onchange="() => _fontSize = size" />
                                <label class="form-check-label" for="@($"fs-{size.ToLowerInvariant()}")">
                                    @size
                                </label>
                            </div>
                        }
                    </div>
                </div>

                @* Language Dropdown *@
                <div class="card mb-4">
                    <div class="card-body">
                        <h6 class="card-title">Language</h6>
                        <select class="form-select" @bind="_language">
                            @foreach (var lang in _languages)
                            {
                                <option value="@lang.Key">@lang.Value</option>
                            }
                        </select>
                    </div>
                </div>

                @* Compact Mode *@
                <div class="card mb-4">
                    <div class="card-body d-flex justify-content-between align-items-center">
                        <div>
                            <h6 class="mb-1">Compact Mode</h6>
                            <small class="text-muted">Reduce spacing and padding throughout the UI</small>
                        </div>
                        <div class="form-check form-switch">
                            <input class="form-check-input" type="checkbox" role="switch"
                                   id="compactMode" @bind="_compactMode" />
                        </div>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @if (_saving)
                    {
                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                    }
                    Save
                </button>

                @if (_successMessage is not null)
                {
                    <div class="alert alert-success alert-dismissible mt-3" role="alert">
                        @_successMessage
                        <button type="button" class="btn-close" @onclick="() => _successMessage = null"></button>
                    </div>
                }

                @if (_errorMessage is not null)
                {
                    <div class="alert alert-danger alert-dismissible mt-3" role="alert">
                        @_errorMessage
                        <button type="button" class="btn-close" @onclick="() => _errorMessage = null"></button>
                    </div>
                }
            </div>

            @* Live Preview *@
            <div class="col-md-5">
                <div class="card">
                    <div class="card-header">
                        <h6 class="mb-0">Live Preview</h6>
                    </div>
                    <div class="card-body preview-area @PreviewThemeClass" style="@PreviewFontStyle">
                        <div class="preview-header @(_compactMode ? "compact" : "")">
                            <strong>Dashboard</strong>
                        </div>
                        <div class="preview-content @(_compactMode ? "compact" : "")">
                            <p class="mb-2">Welcome back! Here's your activity summary.</p>
                            <div class="preview-card @(_compactMode ? "compact" : "")">
                                <small><strong>Recent Activity</strong></small>
                                <div class="preview-item">Item 1 — completed</div>
                                <div class="preview-item">Item 2 — in progress</div>
                            </div>
                            <div class="mt-2 d-flex gap-1">
                                <button class="btn btn-primary btn-sm" disabled>Action</button>
                                <button class="btn btn-outline-secondary btn-sm" disabled>Cancel</button>
                            </div>
                        </div>
                        <div class="preview-footer text-muted @(_compactMode ? "compact" : "")">
                            <small>Language: @_languages.GetValueOrDefault(_language, _language)</small>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
